from pathlib import Path
import json,numpy as np
from PIL import Image,ImageDraw
P=Path('character/crew-idle-walk-check-v1');P.mkdir(exist_ok=True);tracks=[];report={};sheet=Image.new('RGB',(1104,880),'#303b40');dr=ImageDraw.Draw(sheet)
for row,d in enumerate(['south','east','north','west']):
 for col,who in enumerate(['bill','veld','branforth']):
  root=Path('character/crew-runtime-matte-v1')/who;m=json.loads((root/'manifest.json').read_text());idle=next(s for s in m['states'] if s['id']=='idle-'+d);walk=next(s for s in m['states'] if s['id']=='walk-'+d)
  ims=[Image.open(root/f).convert('RGBA') for f in walk['frameFiles']];im=Image.open(root/idle['frameFiles'][0]).convert('RGBA')
  def metrics(im):
   a=np.array(im);r=a[:,:,:3].astype(float);y,x=np.indices(a.shape[:2]);ys=np.where(a[:,:,3]>127)[0];v=r.mean(2);mask=(a[:,:,3]>240)&(y>=60)&(y<153)&(np.ptp(r,axis=2)<18)&(v>25)&(v<90);return np.array([172-ys.min(),*np.median(r[mask],axis=0)])
  iv=metrics(im);wv=np.median([metrics(f) for f in ims],axis=0);report[who+'-'+d]=dict(idleHeadHeight=float(iv[0]),walkMedianHeadHeight=float(wv[0]),heightDelta=float(wv[0]-iv[0]),idleFabric=iv[1:].tolist(),walkFabric=wv[1:].tolist())
  x=col*368;y=row*220;dr.text((x+5,y+3),who+' '+d+'   idle / walk',fill='white');sheet.paste(im,(x,y+25),im);sheet.paste(ims[0],(x+184,y+25),ims[0]);dr.line((x,y+197,x+368,y+197),fill='#83a49c')
  prefix='../crew-runtime-matte-v1/'+who+'/';tracks.append(dict(label=who.title()+' '+d,row=row,col=col,idle=prefix+idle['frameFiles'][0],files=[prefix+f for f in walk['frameFiles']],durations=walk['frameDurationsMs']))
(P/'measurements.json').write_text(json.dumps(report,indent=2));sheet.save(P/'contact.png');print(json.dumps(report))
html='''<!doctype html><title>Crew idle to walk check</title><meta name="viewport" content="width=device-width,initial-scale=1"><style>body{background:#172226;color:#dbe4df;font:17px system-ui;max-width:1200px;margin:24px auto;padding:16px}canvas,img{width:100%;height:auto}button,select{font:inherit}</style><h1>Idle to walk: installed crew</h1><p>Each pair shows idle on the left and moving walk on the right. Rows: south, east, north, west. Both use the same foot anchor and scale.</p><button id="toggle">Pause</button> <select id="mode"><option value="compare">Side by side</option><option value="transition">Idle / walk transition</option></select> <select id="scale"><option value="1">148px inspection</option><option value=".554">82px gameplay</option><option value=".365">54px gameplay</option><option value=".182">27px gameplay</option></select><p id="status">Loading...</p><canvas id="board" width="1104" height="880"></canvas><h2>Static contact sheet</h2><img src="contact.png"><script>const tracks=TRACKS;let ready=false,playing=true,t=0,last=0;const ctx=document.getElementById('board').getContext('2d');function load(src){return new Promise((resolve,reject)=>{const i=new Image;i.onload=()=>resolve(i);i.onerror=reject;i.src=src})}Promise.all(tracks.map(async s=>{s.idleImage=await load(s.idle);s.images=await Promise.all(s.files.map(load));s.total=s.durations.reduce((a,b)=>a+b,0)})).then(()=>{ready=true;document.getElementById('status').textContent='All frames loaded'});document.getElementById('toggle').onclick=e=>{playing=!playing;e.target.textContent=playing?'Pause':'Play'};function draw(now){if(last&&playing)t+=now-last;last=now;if(ready){ctx.fillStyle='#303b40';ctx.fillRect(0,0,1104,880);const z=Number(document.getElementById('scale').value),transition=document.getElementById('mode').value==='transition';tracks.forEach(s=>{let q=t%s.total,i=0;while(i<s.images.length-1&&q>=s.durations[i])q-=s.durations[i++];const x=s.col*368,y=s.row*220;ctx.fillStyle='#dbe4df';ctx.font='15px system-ui';ctx.fillText(s.label,x+5,y+18);ctx.strokeStyle='#83a49c';ctx.beginPath();ctx.moveTo(x,y+197);ctx.lineTo(x+368,y+197);ctx.stroke();const imgs=transition?[(Math.floor(t/1800)%2?s.images[i]:s.idleImage)]:[s.idleImage,s.images[i]];imgs.forEach((im,k)=>ctx.drawImage(im,x+(transition?184:92+k*184)-92*z,y+197-172*z,184*z,184*z))})}requestAnimationFrame(draw)}requestAnimationFrame(draw);</script>''';(P/'index.html').write_text(html.replace('TRACKS',json.dumps(tracks)))
